def checkRow(d, t):
     g = 0
     for row in d:
         a = list(row)
         a.sort()
         a = ''.join(a)
         if 'TXXX' in a or 'XXXX' in a:
             print 'Case #%i: X won' %(t/4+1)
             return 1
         if 'OOOT' in a or 'OOOO' in a:
             print 'Case #%i: O won' %(t/4+1)
             return 1
         if '.' in a:
             g = 10
     return g

 def checkCol(d, t):
     for j in range(4):
         col = []
         for row in d:
             col.append(row[j])
         a = list(col)
         a.sort()
         a = ''.join(a)
         if 'TXXX' in a or 'XXXX' in a:
             print 'Case #%i: X won' %(t/4+1)
             return 1
         if 'OOOT' in a or 'OOOO' in a:
             print 'Case #%i: O won' %(t/4+1)
             return 1
     return 0

 def checkDiag(d1, d2, t):
     a = list(d1)
     b = list(d2)
     a.sort()
     b.sort()
     a = ''.join(a)
     b = ''.join(b)

     if 'TXXX' in a or 'XXXX' in a:
         print 'Case #%i: X won' %(t/4+1)
         return 1
     if 'OOOT' in a or 'OOOO' in a:
         print 'Case #%i: O won' %(t/4+1)
         return 1

     if 'TXXX' in b or 'XXXX' in b:
         print 'Case #%i: X won' %(t/4+1)
         return 1
     if 'OOOT' in b or 'OOOO' in b:
         print 'Case #%i: O won' %(t/4+1)
         return 1
     return 0

