     a = checkRow(data[t:t+4],t)
     if a == 1:
         continue
     b = checkCol(data[t:t+4],t)
     if b:
         continue
     d1 = data[t][0]+data[t+1][1]+data[t+2][2]+data[t+3][3]
     d2 = data[t][3]+data[t+1][2]+data[t+2][1]+data[t+3][0]
     c = checkDiag(d1, d2,t)
     if c:
         continue
     if (a+b+c) == 0:
         print 'Case #%i: Draw' %(t/4+1)
     if a == 10:
         print 'Case #%i: Game has not completed' %(t/4+1)

