 def clear(R,C,b, x, y):
     b = b[:]
     n = 0
     for i in range(max(0,x-1), min(R,x+2)):
         for j in range(max(0,y-1), min(C, y+2)):
             if b[C*i+j] == '*':
                 n += 1
                 b = b[:C*i+j] + '.' + b[C*i+j+1:]
     return b, n
 mem = dict()
