def solve(naomi, ken):
     N = list(sorted(naomi))
     K = list(sorted(ken))
     pd = 0
     while len(N) > 0:
         if N[0] > K[0]:
             pd += 1
             N.pop(0)
             K.pop(0)
         else:
             N.pop(0)
             K.pop(-1)
     pn = 0
     N = list(sorted(naomi))
     K = list(sorted(ken))
     while len(N) > 0:
         n = N.pop(0)
         if n < K[0]:
             K.pop(0)
         else:
             found = None
             for i,k in enumerate(K):
                 if k > n:
                     found = i
                     break
             if found is not None:
                 K.pop(found)
             else:
                 K.pop(0)
                 pn += 1
     return pd,pn

