 def war(N, K):
     points = 0
     j = 0
     for i in range(len(N)):
         while j < len(K) and K[j] < N[i]:
             j += 1
         if j == len(K):
             points += 1
         else:
             j += 1
     return points


 def deceitful_war(N, K):
     return len(N) - war(K, N)


