 def read_case(f):
     return read_ints(f)

 def write_case(f, i, res):
     f.write('Case #%d: '%i)
     if isinstance(res, list):
         res[0][0] = 'c'
         res = '\n'.join(''.join(c for c in r) for r in res)
     f.write('\n%s'%res)
     f.write('\n')

