 def solve_small(case):
     (R, C, M) = case
     if R == 1:
         return 'c' + '.'*(C-M-1) + '*'*M
     if C == 1:
         return '\n'.join(['c'] + ['.']*(R-M-1) + ['*']*M)
     m = R*C - M
     res = [['*']*C for r in range(R)]
     if m == 1:
         return res
     for r in range(2, R+1):
         c = m // r
         z = m % r
         if c < 2 or c + (z>0) > C:
             continue
         if z == 1 and (r < 3 or c < 3):
             continue
         for x in range(r):
             for y in range(c):
                 res[x][y] = '.'
         for y in range(z):
             res[y][c] = '.'
         if z == 1:
             res[z][c] = '.'
             res[r-1][c-1] = '*'
         return res
     return 'Impossible'

 def solve_large(case):
     return solve_small(case)

