 def getIntersection(A,B):
     intersect_list = []
     dict = {};
     for i in range(4):
         if(dict.get(A[i]) <> None):
             dict[A[i]] += 1
             if(intersect_list.count(A[i]) == 0):
                 intersect_list.append(A[i])
         else:
             dict[A[i]] = 1
         if(dict.get(B[i]) <> None):
             dict[B[i]] += 1
             if(intersect_list.count(B[i]) == 0):
                 intersect_list.append(B[i])
         else:
             dict[B[i]] = 1

     return intersect_list

